from itertools import combinations

def pieces(h,w):
    # all 2x2 squares and L-trominoes (2x2 minus one corner) at all positions
    out=[]
    for r in range(h-1):
        for c in range(w-1):
            cells=[(r,c),(r,c+1),(r+1,c),(r+1,c+1)]
            out.append(('S',frozenset(cells)))
            for m in range(4):
                out.append(('L%d'%m, frozenset(cells[:m]+cells[m+1:])))
    return out

def tilings(shape, h, w, limit=200):
    shape=frozenset(shape)
    cand=[p for p in pieces(h,w) if p[1] <= shape]
    res=[]
    def bt(cover, chosen):
        if len(res)>=limit: return
        if cover==shape:
            res.append(list(chosen)); return
        rest=shape-cover
        # cell with fewest options
        best=min(rest, key=lambda cell: sum(1 for t,pcs in cand if cell in pcs))
        for t,pcs in cand:
            if best in pcs and not (pcs & cover):
                bt(cover|pcs, chosen+[(t,pcs)])
    bt(frozenset(), [])
    return res

