def check_tiling(ts, out):
    ts_=tilings(ts,7,7)
    ok=[]
    for tiling in ts_:
        good=True
        for t,pcs in tiling:
            if t=='S':
                if any(out[c]!=1 for c in pcs): good=False;break
            else:
                m=int(t[1]); col=m2c[m]
                if any(out[c]!=col for c in pcs): good=False;break
        if good: ok.append(tiling)
    return len(ts_), ok

